7	
8	// stepClock 按调用次序返回预设时间；用尽后停留在最后一个时间。
9	// 用来模拟一次核对过程中跨过午夜：第一次读取仍在当天，第二次读取已是次日。
10	type stepClock struct {
11		calls int
12		times []time.Time
13	}
14	
15	func (c *stepClock) now() time.Time {
16		i := c.calls
17		if i >= len(c.times) {
18			i = len(c.times) - 1
19		}
20		c.calls++
21		return c.times[i]
22	}
23	
24	// findHistoryCert 返回核对历史中指定编号的证书视图。
25	func findHistoryCert(t *testing.T, r *InstrumentReview, number string) CertificateView {
