38	// 当前计划日为 2026-10-03。核对于 10-03 结束前开始、10-04 才返回时，仍应
39	// 显示可用、两处证书均未到期、计划“今天需校准”。
40	func TestReviewUsesSingleDateAcrossMidnight(t *testing.T) {
41		day3 := mustDate(t, "2026-10-03")
42		day4 := mustDate(t, "2026-10-04")
43		clock := &fakeClock{t: day3}
