65			t.Fatalf("跨午夜的核对仍按 10-03 判断，应可使用，得到 %v", r.Reasons)
66		}
67		if r.Latest == nil || r.Latest.Expired {
68			t.Fatalf("最近证书按核对开始日 10-03 应未到期，得到 %+v", r.Latest)
69		}
